(() => {
'use strict';
const canvas=document.getElementById('game'), ctx=canvas.getContext('2d'), mini=document.getElementById('minimap'), mctx=mini.getContext('2d');
const W=2100,H=1350,TAU=Math.PI*2;
let viewW=1200,viewH=760,scale=1,dpr=1,camera={x:560,y:470},last=performance.now(),elapsed=0,gameOn=false,paused=false,over=false,selected=new Set(),supplies=35,kills=0,wave=0,nextWave=20,cacheFound=0,toastTimer=0,alertTimer=0,soundOn=true,mouse={x:0,y:0},hold=false;
let units=[],zombies=[],bullets=[],sparks=[],caches=[],decor=[],obstacles=[],buildings=[],trees=[],zones=[];
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const roles=[{name:'RANGER',short:'R',color:'#9b6145',hp:110,range:205,damage:23,rate:.76,speed:83},{name:'GUARD',short:'G',color:'#75865c',hp:150,range:158,damage:26,rate:.92,speed:71},{name:'SCOUT',short:'S',color:'#637a7b',hp:94,range:170,damage:17,rate:.48,speed:103},{name:'MEDIC',short:'✚',color:'#aa8b56',hp:105,range:155,damage:12,rate:1.04,speed:78,medic:true}];
const mkUnit=(role,x,y)=>({id:Math.random(),role:role.name,short:role.short,color:role.color,x,y,hp:role.hp,max:role.hp,range:role.range,damage:role.damage,rate:role.rate,speed:role.speed,medic:!!role.medic,selected:false,target:null,attackCd:rand(0,.5),facing:0,dead:false,hold:false,medCd:0});
function init(){
 units=[mkUnit(roles[0],478,440),mkUnit(roles[1],430,480),mkUnit(roles[2],485,505),mkUnit(roles[3],423,430)];
 selected=new Set(units.map(u=>u.id));
 caches=[{x:840,y:330,found:false,label:'SUPPLY CACHE'},{x:1305,y:785,found:false,label:'SUPPLY CACHE'},{x:1710,y:360,found:false,label:'SUPPLY CACHE'}];
 zombies=[];bullets=[];sparks=[];elapsed=0;kills=0;supplies=35;wave=0;nextWave=19;cacheFound=0;over=false;hold=false;camera={x:560,y:470};
 decor=[];trees=[];obstacles=[];buildings=[];zones=[];
 makeMap(); syncUI();
}
function makeMap(){
 // Winding roads and broken settlement lots
 zones=[{x:80,y:265,w:620,h:130},{x:675,y:505,w:430,h:125},{x:1100,y:700,w:410,h:135},{x:1460,y:390,w:420,h:135},{x:1660,y:970,w:330,h:140}];
 buildings=[{x:250,y:200,w:155,h:103,kind:'house'},{x:575,y:300,w:130,h:110,kind:'chapel'},{x:960,y:180,w:180,h:130,kind:'ruin'},{x:1130,y:535,w:158,h:115,kind:'house'},{x:1500,y:225,w:180,h:135,kind:'manor'},{x:1725,y:765,w:160,h:120,kind:'house'},{x:340,y:745,w:200,h:145,kind:'mill'},{x:880,y:930,w:165,h:118,kind:'ruin'}];
 for(const b of buildings)obstacles.push({x:b.x+b.w/2,y:b.y+b.h/2,r:Math.max(b.w,b.h)*.43});
 for(let i=0;i<300;i++){let x=rand(35,W-30),y=rand(30,H-30); if(zones.some(z=>x>z.x&&x<z.x+z.w&&y>z.y&&y<z.y+z.h))continue; decor.push({x,y,r:rand(2,9),type:Math.random()<.58?'grass':'stone',rot:rand(0,6)});}
 // Forest framing and scattered trees
 for(let i=0;i<260;i++){let side=Math.random(),x,y;if(side<.28){x=rand(20,W-20);y=rand(10,185)}else if(side<.56){x=rand(20,W-20);y=rand(H-190,H-12)}else if(side<.78){x=rand(10,230);y=rand(170,H-170)}else{x=rand(W-240,W-15);y=rand(170,H-170)}if(zones.some(z=>x>z.x-35&&x<z.x+z.w+35&&y>z.y-30&&y<z.y+z.h+30))continue;trees.push({x,y,r:rand(17,34),tone:Math.floor(rand(0,4))});}
 // scattered grave markers and debris
 for(let i=0;i<38;i++)decor.push({x:rand(180,W-160),y:rand(170,H-160),r:rand(8,15),type:'grave',rot:rand(-.15,.15)});
}
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));scale=r.height/760;viewH=r.height/scale;viewW=r.width/scale;}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.3;}
function setPaused(v){paused=v;document.body.classList.toggle('paused',paused);document.getElementById('pauseButton').textContent=paused?'▶':'Ⅱ';}
function addZombie(x,y,type='walker'){const boss=type==='abomination';zombies.push({x,y,hp:boss?640:type==='brute'?180:70,max:boss?640:type==='brute'?180:70,type,speed:boss?29:type==='brute'?36:type==='runner'?63:43,damage:boss?30:type==='brute'?20:12,range:boss?38:29,attackCd:0,hitFlash:0,dead:false,rot:rand(0,TAU),id:Math.random()});}
function spawnWave(){wave++;const count=5+wave*3;for(let i=0;i<count;i++){const gate=i%4,points=[[85,390],[1120,75],[1985,580],[1550,1260]],p=points[gate];addZombie(p[0]+rand(-85,85),p[1]+rand(-55,55),wave>=2&&Math.random()<.2?'runner':'walker');}if(wave>=3){addZombie(1830,570,'abomination');toast('ABOMINATION DETECTED — HOLD THE LINE');}else toast(`WAVE ${wave} INCOMING — ${count} HOSTILES`);alertTimer=3.2;nextWave=elapsed+34;}
function syncUI(){
 document.getElementById('supply').textContent=supplies;document.getElementById('kills').textContent=kills;document.getElementById('cacheCount').textContent=`${cacheFound} / 3`;document.getElementById('squadCount').textContent=`${units.filter(u=>!u.dead).length.toString().padStart(2,'0')} / 08`;
 const list=document.getElementById('unitList');list.innerHTML='';units.forEach(u=>{const b=document.createElement('button');b.className='unit-card'+(selected.has(u.id)?' selected':'')+(u.dead?' dead':'');b.innerHTML=`<span class="unit-art">${u.short}</span><span class="healthbar"><i style="width:${Math.max(0,u.hp/u.max*100)}%;background:${u.hp/u.max<.28?'#b74f40':'#91a96d'}"></i></span><span class="unit-title">${u.role.slice(0,4)}</span>`;b.onclick=()=>{if(u.dead)return;selected=new Set([u.id]);syncUI()};list.appendChild(b)});
 const live=[...selected].map(id=>units.find(u=>u.id===id)).filter(Boolean);document.getElementById('selectedName').innerHTML=live.length===units.filter(u=>!u.dead).length?'ALL SURVIVORS <span>• READY</span>':live.length===1?`${live[0].role} <span>• ${Math.ceil(live[0].hp/live[0].max*100)}% CONDITION</span>`:`${live.length} SURVIVORS <span>• SELECTED</span>`;
}
function setObjective(){const steps=document.querySelectorAll('.objective-step');steps[0].classList.toggle('done',cacheFound>=3);steps[0].classList.toggle('active',cacheFound<3);steps[1].classList.toggle('active',cacheFound>=3);steps[1].classList.toggle('done',over&&!units.every(u=>u.dead));steps[1].querySelector('em').textContent=cacheFound>=3?'BEACON LIVE':'LOCKED';document.getElementById('objectiveText').textContent=cacheFound>=3?'Extraction beacon active. Reach it with a survivor to get out.':'Recover 3 supply caches, then reach the extraction beacon.';document.getElementById('extractLabel').textContent=cacheFound>=3?'EXTRACTION · ACTIVE':'EXTRACTION · LOCKED';}

