function setObjective(){const steps=document.querySelectorAll('.objective-step');steps[0].classList.toggle('done',cacheFound>=3);steps[0].classList.toggle('active',cacheFound<3);steps[1].classList.toggle('active',cacheFound>=3);steps[1].classList.toggle('done',over&&!units.every(u=>u.dead));steps[1].querySelector('em').textContent=cacheFound>=3?'BEACON LIVE':'LOCKED';document.getElementById('objectiveText').textContent=cacheFound>=3?'Extraction beacon active. Reach it with a survivor to get out.':'Recover 3 supply caches, then reach the extraction beacon.';document.getElementById('extractLabel').textContent=cacheFound>=3?'EXTRACTION · ACTIVE':'EXTRACTION · LOCKED';}
function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
function drawGround(){
 ctx.fillStyle='#41483b';ctx.fillRect(0,0,W,H);
 // subtle, irregular ground grain
 for(let i=0;i<decor.length;i++){const d=decor[i];if(d.type==='grass'){ctx.strokeStyle=i%2?'#73785c22':'#222c2029';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x+d.r*.5,d.y-d.r);ctx.moveTo(d.x+3,d.y+1);ctx.lineTo(d.x+d.r,d.y-d.r*.4);ctx.stroke();}else if(d.type==='stone'){ctx.fillStyle='#90907a29';ctx.beginPath();ctx.ellipse(d.x,d.y,d.r,d.r*.52,d.rot,0,TAU);ctx.fill();}else drawGrave(d);}
 // muddy cart tracks
 ctx.lineCap='round';ctx.strokeStyle='#262e262e';ctx.lineWidth=28;ctx.beginPath();ctx.moveTo(-20,405);ctx.bezierCurveTo(340,365,520,490,810,555);ctx.bezierCurveTo(1160,635,1260,810,1600,730);ctx.bezierCurveTo(1850,690,1930,610,2140,650);ctx.stroke();ctx.strokeStyle='#9b8a6330';ctx.lineWidth=2;ctx.setLineDash([17,22]);ctx.beginPath();ctx.moveTo(-20,405);ctx.bezierCurveTo(340,365,520,490,810,555);ctx.bezierCurveTo(1160,635,1260,810,1600,730);ctx.bezierCurveTo(1850,690,1930,610,2140,650);ctx.stroke();ctx.setLineDash([]);
 // ruined plots
 for(const z of zones){ctx.fillStyle='#33392e';ctx.fillRect(z.x,z.y,z.w,z.h);ctx.strokeStyle='#a49a7440';ctx.lineWidth=2;ctx.setLineDash([12,8]);ctx.strokeRect(z.x+4,z.y+4,z.w-8,z.h-8);ctx.setLineDash([]);}
 for(const t of trees)drawTree(t);
 for(const b of buildings)drawBuilding(b);
 // blood pools and debris scattered near roads
 for(let i=0;i<15;i++){let x=160+(i*137)%1750,y=245+(i*223)%930;ctx.fillStyle=i%3?'#713c3535':'#392f2a40';ctx.beginPath();ctx.ellipse(x,y,rand(9,24),rand(4,10),rand(-.7,.7),0,TAU);ctx.fill();}
}
function drawGrave(d){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.fillStyle='#252c25';ctx.fillRect(-d.r*.55,2,d.r*1.1,4);ctx.fillStyle='#777b6b';ctx.beginPath();ctx.moveTo(-d.r*.38,2);ctx.lineTo(-d.r*.3,-d.r*.7);ctx.lineTo(0,-d.r);ctx.lineTo(d.r*.3,-d.r*.7);ctx.lineTo(d.r*.4,2);ctx.closePath();ctx.fill();ctx.strokeStyle='#a7a28a66';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-d.r*.2,-d.r*.55);ctx.lineTo(d.r*.2,-d.r*.55);ctx.moveTo(0,-d.r*.72);ctx.lineTo(0,-d.r*.3);ctx.stroke();ctx.restore();}
function drawTree(t){ctx.fillStyle='#151c17aa';ctx.beginPath();ctx.ellipse(t.x+8,t.y+11,t.r*1.1,t.r*.72,0,0,TAU);ctx.fill();ctx.fillStyle=['#27382b','#30402e','#374331','#24332b'][t.tone];ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,TAU);ctx.fill();ctx.fillStyle=['#42513b','#4a553c','#4f5941','#394a3b'][t.tone];ctx.beginPath();ctx.arc(t.x-t.r*.2,t.y-t.r*.2,t.r*.63,0,TAU);ctx.fill();ctx.fillStyle='#84905a22';ctx.beginPath();ctx.arc(t.x-t.r*.35,t.y-t.r*.37,t.r*.23,0,TAU);ctx.fill();}
function drawBuilding(b){ctx.save();ctx.translate(b.x,b.y);const {w,h}=b;ctx.fillStyle='#1b211ccc';ctx.fillRect(-7,h-4,w+14,11);ctx.fillStyle='#555345';ctx.fillRect(0,18,w,h-12);ctx.fillStyle='#766e57';ctx.beginPath();ctx.moveTo(-10,22);ctx.lineTo(w*.48,-18);ctx.lineTo(w+12,20);ctx.lineTo(w+3,34);ctx.lineTo(w*.5,4);ctx.lineTo(4,36);ctx.closePath();ctx.fill();ctx.strokeStyle='#b4a57b55';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#363a30';ctx.fillRect(12,40,w-24,h-47);
 for(let x=22;x<w-15;x+=38){ctx.fillStyle='#242c28';ctx.fillRect(x,50,12,23);ctx.fillStyle='#a9894e55';ctx.fillRect(x+4,54,4,9);}
 ctx.fillStyle='#292d27';ctx.fillRect(w*.44,h-42,20,34);ctx.fillStyle='#9e8d6540';ctx.fillRect(w*.44+3,h-38,14,25);
 if(b.kind==='chapel'){ctx.fillStyle='#d2c49a';ctx.fillRect(w*.47,-39,8,27);ctx.fillRect(w*.4,-32,22,6)}
 if(b.kind==='ruin'){ctx.clearRect(w*.58,35,34,40);ctx.fillStyle='#41483b';ctx.fillRect(w*.58,35,34,40);ctx.fillStyle='#847a61';ctx.fillRect(20,14,w-40,8)}
 if(b.kind==='manor'){ctx.fillStyle='#6b322d';ctx.fillRect(w*.45,-3,20,27);ctx.strokeStyle='#c3985e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(w*.5,-4);ctx.lineTo(w*.5,24);ctx.stroke();}
 ctx.restore();}
function drawCache(cache){if(cache.found)return;ctx.save();ctx.translate(cache.x,cache.y);ctx.fillStyle='#171d17bb';ctx.beginPath();ctx.ellipse(0,8,27,15,0,0,TAU);ctx.fill();ctx.shadowColor='#d0a957';ctx.shadowBlur=14;ctx.fillStyle='#917243';ctx.fillRect(-17,-15,34,25);ctx.shadowBlur=0;ctx.fillStyle='#c3a366';ctx.fillRect(-19,-18,38,7);ctx.fillStyle='#473e2b';ctx.fillRect(-2,-18,4,24);ctx.fillStyle='#e2d18a';ctx.beginPath();ctx.arc(0,-27,3,0,TAU);ctx.fill();ctx.restore();}
function drawBeacon(){ctx.save();ctx.translate(1910,1050);const pulse=.5+.5*Math.sin(elapsed*3);ctx.strokeStyle=cacheFound>=3?`rgba(155,205,127,${.35+pulse*.45})`:'#b9544380';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,30+pulse*10,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(0,0,19,0,TAU);ctx.stroke();ctx.fillStyle=cacheFound>=3?'#b8e595':'#d2634e';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=18;ctx.beginPath();ctx.arc(0,0,5+pulse*3,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#c4b998';ctx.font='9px DM Mono';ctx.textAlign='center';ctx.fillText('EXTRACTION',0,48);ctx.restore();}

