function drawMinimap(){const w=mini.width,h=mini.height;mctx.fillStyle='#222b22';mctx.fillRect(0,0,w,h);mctx.fillStyle='#363e31';mctx.fillRect(0,0,w,h);mctx.strokeStyle='#91826255';mctx.lineWidth=4;mctx.beginPath();mctx.moveTo(0,h*.32);mctx.lineTo(w*.37,h*.38);mctx.lineTo(w*.65,h*.58);mctx.lineTo(w,h*.48);mctx.stroke();for(const b of buildings){mctx.fillStyle='#77745c';mctx.fillRect(b.x/W*w,b.y/H*h,b.w/W*w,b.h/H*h);}for(const c of caches)if(!c.found){mctx.fillStyle='#e2ba64';mctx.fillRect(c.x/W*w-2,c.y/H*h-2,4,4);}mctx.fillStyle='#cc5546';for(const z of zombies){if(!z.dead){mctx.beginPath();mctx.arc(z.x/W*w,z.y/H*h,z.type==='abomination'?3:1.6,0,TAU);mctx.fill();}}mctx.fillStyle='#b9d583';for(const u of units){if(!u.dead){mctx.beginPath();mctx.arc(u.x/W*w,u.y/H*h,2,0,TAU);mctx.fill();}}mctx.strokeStyle='#e2d2a0';mctx.lineWidth=1;mctx.strokeRect((camera.x-viewW/2)/W*w,(camera.y-viewH/2)/H*h,viewW/W*w,viewH/H*h);mctx.fillStyle=cacheFound>=3?'#9cc577':'#bd5e4d';mctx.beginPath();mctx.arc(1910/W*w,1050/H*h,3,0,TAU);mctx.fill();}
function findTarget(u){let best=null,bd=Infinity;for(const z of zombies){if(z.dead)continue;const d=dist(u,z);if(d<u.range&&d<bd){bd=d;best=z;}}return best;}
function fire(u,z){if(u.attackCd>0)return;u.attackCd=u.rate;u.facing=Math.atan2(z.y-u.y,z.x-u.x);bullets.push({x:u.x+Math.cos(u.facing)*14,y:u.y+Math.sin(u.facing)*14,vx:Math.cos(u.facing)*530,vy:Math.sin(u.facing)*530,target:z,damage:u.damage,color:u.role==='GUARD'?'#d3b66b':'#f1dfaa',life:.55});sparks.push({x:u.x+Math.cos(u.facing)*16,y:u.y+Math.sin(u.facing)*16,r:3,color:'#ffdb87',life:.12});}
function update(dt){if(!gameOn||paused||over)return;elapsed+=dt;if(elapsed>=nextWave)spawnWave();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show');}if(alertTimer>0){alertTimer-=dt;if(alertTimer<=0)document.getElementById('waveAlert').classList.remove('show');}
 for(const u of units){if(u.dead)continue;u.attackCd-=dt;u.medCd-=dt;const target=findTarget(u);if(target){fire(u,target);}else if(u.target&&!u.hold){let dx=u.target.x-u.x,dy=u.target.y-u.y,d=Math.hypot(dx,dy);if(d>11){u.facing=Math.atan2(dy,dx);u.x+=dx/d*u.speed*dt;u.y+=dy/d*u.speed*dt;}else u.target=null;}
 if(u.medic&&u.medCd<=0){const ally=units.find(a=>!a.dead&&a!==u&&a.hp<a.max-5&&dist(a,u)<92);if(ally){ally.hp=Math.min(ally.max,ally.hp+11);u.medCd=1.8;sparks.push({x:ally.x,y:ally.y-14,r:5,color:'#bfd58a',life:.32});}}
 for(const c of caches){if(!c.found&&dist(c,u)<48){c.found=true;cacheFound++;supplies+=30;toast(`SUPPLY CACHE SECURED +30 SUPPLIES (${cacheFound}/3)`);setObjective();syncUI();if(cacheFound===3){toast('EXTRACTION BEACON ACTIVATED');nextWave=Math.min(nextWave,elapsed+8);}}}
 }
 for(const z of zombies){if(z.dead)continue;z.hitFlash=Math.max(0,z.hitFlash-dt);const targets=units.filter(u=>!u.dead);if(!targets.length)continue;let target=targets.reduce((a,b)=>dist(z,a)<dist(z,b)?a:b);const d=dist(z,target);if(d>z.range){z.rot=Math.atan2(target.y-z.y,target.x-z.x);z.x+=Math.cos(z.rot)*z.speed*dt;z.y+=Math.sin(z.rot)*z.speed*dt;}else{z.attackCd-=dt;if(z.attackCd<=0){z.attackCd=z.type==='abomination'?1.25:1.05;target.hp-=z.damage;sparks.push({x:target.x,y:target.y,r:4,color:'#bd5342',life:.3});if(target.hp<=0){target.dead=true;selected.delete(target.id);toast(`${target.role} HAS FALLEN`);syncUI();}}}}
 for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(!b.target||b.target.dead)continue;if(dist(b,b.target)<15){b.target.hp-=b.damage;b.target.hitFlash=.12;b.life=0;sparks.push({x:b.target.x+rand(-7,7),y:b.target.y+rand(-7,7),r:rand(2,4),color:'#c87558',life:.22});if(b.target.hp<=0){b.target.dead=true;kills++;supplies+=b.target.type==='abomination'?20:0;syncUI();}}}bullets=bullets.filter(b=>b.life>0);for(const s of sparks){s.life-=dt;s.y-=dt*12;}sparks=sparks.filter(s=>s.life>0);
 const live=units.filter(u=>!u.dead);if(!live.length){finish(false);return;}if(cacheFound>=3&&live.some(u=>dist(u,{x:1910,y:1050})<60)){finish(true);return;}camera.x+=(clamp(live.reduce((n,u)=>n+u.x,0)/live.length,viewW/2,W-viewW/2)-camera.x)*dt*1.3;camera.y+=(clamp(live.reduce((n,u)=>n+u.y,0)/live.length,viewH/2,H-viewH/2)-camera.y)*dt*1.3;
 document.getElementById('clock').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;document.getElementById('kills').textContent=kills;document.getElementById('supply').textContent=supplies;const threat=Math.min(5,2+Math.floor(wave/1.5));document.querySelectorAll('.threat-pips i').forEach((p,i)=>p.classList.toggle('lit',i<threat));
}

