 function medkit(){if(!gameOn||paused)return;if(supplies<25){toast('NOT ENOUGH SUPPLIES');return;}const hurt=units.filter(u=>!u.dead&&u.hp<u.max);if(!hurt.length){toast('SQUAD IS AT FULL STRENGTH');return;}supplies-=25;hurt.forEach(u=>{u.hp=Math.min(u.max,u.hp+55);sparks.push({x:u.x,y:u.y-13,r:7,color:'#bfd58a',life:.45});});syncUI();toast('FIELD DRESSING APPLIED');}
 document.getElementById('deployButton').onclick=()=>{gameOn=true;document.getElementById('briefing').classList.add('hidden');camera={x:560,y:470};toast('SQUAD DEPLOYED — LOCATE THE SUPPLY CACHES');};document.getElementById('pauseButton').onclick=()=>setPaused(!paused);document.getElementById('selectAll').onclick=()=>{selected=new Set(units.filter(u=>!u.dead).map(u=>u.id));syncUI();};document.getElementById('holdButton').onclick=()=>{hold=!hold;selected.forEach(id=>{const u=units.find(v=>v.id===id);if(u){u.hold=hold;u.target=null;}});toast(hold?'SQUAD HOLDING POSITION':'SQUAD RESUMING');};document.getElementById('recruitButton').onclick=recruit;document.getElementById('medButton').onclick=medkit;document.getElementById('restartButton').onclick=()=>{document.getElementById('resultOverlay').classList.add('hidden');init();gameOn=true;document.getElementById('briefing').classList.add('hidden');};document.getElementById('soundButton').onclick=e=>{soundOn=!soundOn;e.currentTarget.innerHTML=`SOUND: <b>${soundOn?'ON':'OFF'}</b>`;toast(`SOUND ${soundOn?'ENABLED':'DISABLED'}`);};
 function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;if(gameOn&&!paused&&!over){if(keys.w||keys.arrowup)camera.y-=280*dt;if(keys.s||keys.arrowdown)camera.y+=280*dt;if(keys.a&&false)camera.x-=280*dt;if(keys.d||keys.arrowright)camera.x+=280*dt;camera.x=clamp(camera.x,viewW/2,W-viewW/2);camera.y=clamp(camera.y,viewH/2,H-viewH/2);}update(dt);draw();requestAnimationFrame(frame);}

